var doc = Document;
// Goal: read a wall's parameters, change two of them (a text and a length), and remove an element
// the user no longer wants. Reads at top level; the writes inside one WithTransaction block.
// A blank project has levels already; take the lowest one rather than creating another.
Autodesk.Revit.DB.Level level = null;
foreach (Autodesk.Revit.DB.Level l in new Autodesk.Revit.DB.FilteredElementCollector(doc).OfClass(typeof(Autodesk.Revit.DB.Level))) {
  if (level == null || l.Elevation < level.Elevation) level = l;
}

double z = level.Elevation;
return Connector.WithTransaction(doc, () => {
  var wall = Autodesk.Revit.DB.Wall.Create(doc, Autodesk.Revit.DB.Line.CreateBound(new Autodesk.Revit.DB.XYZ(0, 0, z), new Autodesk.Revit.DB.XYZ(12, 0, z)), level.Id, false);
  var scratch = Autodesk.Revit.DB.Wall.Create(doc, Autodesk.Revit.DB.Line.CreateBound(new Autodesk.Revit.DB.XYZ(0, 40, z), new Autodesk.Revit.DB.XYZ(12, 40, z)), level.Id, false);
  doc.Regenerate();

  // 1. Two ways to reach a parameter. By display name (LookupParameter) is what a user says, but
  //    the name is localized and can be shared by several parameters; by BuiltInParameter id is
  //    exact. Prefer the id for built-ins, the name for project or shared parameters.
  var byName = wall.LookupParameter("Comments");
  var byId = wall.get_Parameter(Autodesk.Revit.DB.BuiltInParameter.ALL_MODEL_INSTANCE_COMMENTS);
  bool sameParameter = byName != null && byId != null && byName.Id == byId.Id;

  // 2. Before writing, check the storage type and that it is not read-only: Set on a read-only
  //    parameter throws (Autodesk.Revit.Exceptions.InvalidOperationException), which rolls the
  //    block back. Choose the Set overload by StorageType: String, Double, Integer or ElementId.
  string commentsStorage = byId.StorageType.ToString();
  bool commentsWritable = !byId.IsReadOnly;
  if (commentsWritable) byId.Set("fire-rated partition");
  string commentReadBack = wall.get_Parameter(Autodesk.Revit.DB.BuiltInParameter.ALL_MODEL_INSTANCE_COMMENTS).AsString();

  // 3. A length parameter is a Double in Revit's internal unit (decimal feet), whatever the
  //    project's display units are. Convert from the user's unit with UnitUtils and UnitTypeId.
  var height = wall.get_Parameter(Autodesk.Revit.DB.BuiltInParameter.WALL_USER_HEIGHT_PARAM);
  double wantedMm = 3000.0;
  double internalFeet = Autodesk.Revit.DB.UnitUtils.ConvertToInternalUnits(wantedMm, Autodesk.Revit.DB.UnitTypeId.Millimeters);
  bool heightWritable = height != null && !height.IsReadOnly && height.StorageType == Autodesk.Revit.DB.StorageType.Double;
  if (heightWritable) height.Set(internalFeet);
  doc.Regenerate();
  double heightMmReadBack = Autodesk.Revit.DB.UnitUtils.ConvertFromInternalUnits(
      wall.get_Parameter(Autodesk.Revit.DB.BuiltInParameter.WALL_USER_HEIGHT_PARAM).AsDouble(), Autodesk.Revit.DB.UnitTypeId.Millimeters);

  // 4. A read-only parameter, for contrast: the wall's computed Length. Reading is fine; Set throws.
  var length = wall.get_Parameter(Autodesk.Revit.DB.BuiltInParameter.CURVE_ELEM_LENGTH);
  bool lengthReadOnly = length != null && length.IsReadOnly;

  // 5. Delete an element: Document.Delete takes the id and returns every id removed with it
  //    (hosted elements, dimensions referencing it). Afterwards GetElement returns null.
  var scratchId = scratch.Id;
  var removed = doc.Delete(scratchId);
  bool gone = doc.GetElement(scratchId) == null;

  // 6. Return a projection of what changed.
  return new {
    wallId = wall.Id.Value, sameParameter, commentsStorage, commentsWritable, commentReadBack,
    heightMmRequested = wantedMm, heightMmReadBack, heightRoundTripped = System.Math.Abs(heightMmReadBack - wantedMm) < 0.01,
    lengthReadOnly, deletedCount = removed.Count, scratchGone = gone
  };
});
